using Payments;

namespace Payments.Tests;

/// <summary>Simple in-memory fake for <see cref="IPaymentProvider"/>.</summary>
internal sealed class FakePaymentProvider : IPaymentProvider
{
    private int _chargeCounter;
    private int _refundCounter;

    public bool ShouldSucceed { get; set; } = true;
    public Exception? ExceptionToThrow { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal? LastChargeAmount { get; private set; }
    public string? LastRefundChargeId { get; private set; }

    public Task<ChargeResult> CreateChargeAsync(string cardToken, decimal amount)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastCardToken = cardToken;
        LastChargeAmount = amount;

        var id = $"ch_{Interlocked.Increment(ref _chargeCounter)}";
        return Task.FromResult(new ChargeResult(id, ShouldSucceed,
            ShouldSucceed ? null : "declined"));
    }

    public Task<RefundResult> CreateRefundAsync(string chargeId)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastRefundChargeId = chargeId;

        var id = $"re_{Interlocked.Increment(ref _refundCounter)}";
        return Task.FromResult(new RefundResult(id, ShouldSucceed,
            ShouldSucceed ? null : "refund_failed"));
    }
}

