using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    // ──────────────────────────────────────────────
    //  Constructor validation
    // ──────────────────────────────────────────────

    [TestMethod]
    public void Ctor_NullProvider_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync — happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
        Assert.IsNull(result.ErrorMessage);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ForwardsCardTokenToProvider()
    {
        await _gateway.ChargeAsync("tok_mastercard", 10m);

        Assert.AreEqual("tok_mastercard", _provider.LastCardToken);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ForwardsAmountToProvider()
    {
        await _gateway.ChargeAsync("tok_visa", 123.45m);

        Assert.AreEqual(123.45m, _provider.LastChargeAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclines_ReturnsFailureResult()
    {
        _provider.ShouldSucceed = false;

        var result = await _gateway.ChargeAsync("tok_visa", 10m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual("declined", result.ErrorMessage);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync — input validation
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null token")]
    [DataRow("", DisplayName = "empty token")]
    [DataRow("   ", DisplayName = "whitespace token")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? badToken)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(badToken!, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-0.01)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double badAmount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)badAmount));

        Assert.AreEqual("amount", ex.ParamName);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync — provider exceptions bubble up
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("gateway timeout");

        var ex = await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_visa", 5m));

        Assert.AreEqual("gateway timeout", ex.Message);
    }

    // ──────────────────────────────────────────────
    //  RefundAsync — happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
        Assert.IsNull(result.ErrorMessage);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ForwardsChargeIdToProvider()
    {
        await _gateway.RefundAsync("ch_456");

        Assert.AreEqual("ch_456", _provider.LastRefundChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderFails_ReturnsFailureResult()
    {
        _provider.ShouldSucceed = false;

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
        Assert.AreEqual("refund_failed", result.ErrorMessage);
    }

    // ──────────────────────────────────────────────
    //  RefundAsync — input validation
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "null chargeId")]
    [DataRow("", DisplayName = "empty chargeId")]
    [DataRow("   ", DisplayName = "whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? badId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(badId!));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync — provider exceptions bubble up
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("network error");

        var ex = await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_123"));

        Assert.AreEqual("network error", ex.Message);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync — boundary amounts
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(0.01, DisplayName = "smallest valid amount")]
    [DataRow(999999.99, DisplayName = "large amount")]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    // ──────────────────────────────────────────────
    //  Unique IDs per call
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_MultipleCalls_ReturnsDistinctChargeIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_visa", 10m);
        var r2 = await _gateway.ChargeAsync("tok_visa", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_MultipleCalls_ReturnsDistinctRefundIds()
    {
        var r1 = await _gateway.RefundAsync("ch_1");
        var r2 = await _gateway.RefundAsync("ch_2");

        Assert.AreNotEqual(r1.RefundId, r2.RefundId);
    }
}

